manual.pi:
void handle_url(string this_url)
{
  write("Fetching URL '" + this_url + "'...");
  Query web_page = get_url(this_url);
  if(web_page == 0)
  {
    write(" Failed.\n");
    return;
  }
  write(" Done.\n");
  write("This is the contents of '" + this_url + "':\n\n");
  string page_contents = web_page->data();
  write(page_contents + "\n");
} // handle_url
